action.command:
cd /tmp; python3 - <<'EOF'
import zipfile, re
z=zipfile.ZipFile('logic.jar')
pat=re.compile(rb'(pkg\.github|maven\.pkg|GITHUB_TOKEN|swcodeGpr|gpr\.user|gpr\.key|github)', re.I)
hits={}
for n in z.namelist():
    if n.endswith(('.class','.properties','.kts','.txt','.xml','.json')):
        try: d=z.read(n)
        except Exception: continue
        m=pat.findall(d)
        if m: hits[n]=sorted(set(x.decode(errors='replace') for x in m))
for k,v in hits.items():
    print(k, v)
print("total", len(hits))
EOF

